              <span>{key}</span>
            </td>
            <td>
              <span style={{ color: typeColorMap[valueType] }}>{value.toString()}</span>
            </td>
          </tr>
        )
      }
    } else {
      return (
        <tr key={key}>
          <td>
            <span>{key}</span>
          </td>
          <td>
            <JsonToTable data={value} />
          </td>
        </tr>
      )
    }
  }

  const renderTable = (data) => {
    if (Array.isArray(data)) {
      return <tbody>{data.map(renderTableContent)}</tbody>
    } else if (typeof data === 'object' && data !== null) {
      return <tbody>{Object.entries(data).map(([key, value]) => renderKeyValue(key, value))}</tbody>
    } else {
      return <span style={{ color: typeColorMap[typeof data] || 'black' }}>{data}</span>
    }
  }

  return (
    <div>
      <table className="table-node" style={{ borderSpacing: '0' }}>
        {renderTable(data)}
      </table>
    </div>
  )
}

