    public AbstractSubstitutionCost DCostFunction { get; set; }

    public double GapCost { get; set; }

    public override string LongDescriptionString => "Implements the Needleman-Wunch algorithm providing an edit distance based similarity measure between two strings";

    public override string ShortDescriptionString => "NeedlemanWunch";

    public NeedlemanWunch()
        : this(2.0, new SubCostRange0To1())
    {
    }

    public NeedlemanWunch(AbstractSubstitutionCost costFunction)
        : this(2.0, costFunction)
    {
    }

    public NeedlemanWunch(double costG)
        : this(costG, new SubCostRange0To1())
    {
    }

    public NeedlemanWunch(double costG, AbstractSubstitutionCost costFunction)
    {
        _estimatedTimingConstant = 0.00018420000560581684;
        GapCost = costG;
        DCostFunction = costFunction;
    }

    public override double GetSimilarity(string firstWord, string secondWord)
    {
        if (firstWord == null || secondWord == null)
        {
            return 0.0;
        }

        double num = GetUnnormalisedSimilarity(firstWord, secondWord);
        double num2 = Math.Max(firstWord.Length, secondWord.Length);
        double num3 = num2;
        num2 = ((!(DCostFunction.MaxCost > GapCost)) ? (num2 * GapCost) : (num2 * DCostFunction.MaxCost));
        num3 = ((!(DCostFunction.MinCost < GapCost)) ? (num3 * GapCost) : (num3 * DCostFunction.MinCost));
        if (num3 < 0.0)
        {
            num2 -= num3;
            num -= num3;
        }

        if (num2 == 0.0)
        {
            return 1.0;
        }

        return 1.0 - num / num2;
    }

    public override string GetSimilarityExplained(string firstWord, string secondWord)
    {
        throw new NotImplementedException();
    }

    public override double GetSimilarityTimingEstimated(string firstWord, string secondWord)
    {
        if (firstWord != null && secondWord != null)
        {
            double num = firstWord.Length;
            double num2 = secondWord.Length;
            return num * num2 * _estimatedTimingConstant;
        }

        return 0.0;
    }

    public override double GetUnnormalisedSimilarity(string firstWord, string secondWord)
    {
        if (firstWord == null || secondWord == null)
        {
            return 0.0;
        }

        int length = firstWord.Length;
        int length2 = secondWord.Length;
        if (length == 0)
        {
            return length2;
        }

        if (length2 == 0)
        {
            return length;
        }

        double[][] array = new double[length + 1][];
        for (int i = 0; i < length + 1; i++)
        {
            array[i] = new double[length2 + 1];
        }

        for (int j = 0; j <= length; j++)
        {
            array[j][0] = j;
        }

        for (int k = 0; k <= length2; k++)
        {
            array[0][k] = k;
        }

        for (int l = 1; l <= length; l++)
        {
            for (int m = 1; m <= length2; m++)
            {
                double cost = DCostFunction.GetCost(firstWord, l - 1, secondWord, m - 1);
                array[l][m] = MathFunctions.MinOf3(array[l - 1][m] + GapCost, array[l][m - 1] + GapCost, array[l - 1][m - 1] + cost);
            }
        }

        return array[length][length2];
    }
}
