export function OracleThinking({
  apiEndpoint,
  token,
  dbName,
  reportId,
  onStreamClosed = () => {},
}: OracleThinkingProps) {
  const [thinkingSteps, setThinkingSteps] = useState<any[]>([]);
  const [rawMessages, setRawMessages] = useState<string>("");

  useEffect(() => {
    let isCancelled = false;

    // A controller to abort fetch if the component unmounts
    const controller = new AbortController();

    async function fetchThinkingStream() {
      try {
        // Start the streaming GET request
        const response = await fetch(
          `${apiEndpoint}/oracle/get_report_thinking_status?report_id=${reportId}&x_auth_token=${token}`,
          {
            headers: {
              "X-Auth-Token": token,
            },
            signal: controller.signal,
          }
        );

        if (!response.ok) {
          console.error("Stream request failed:", response.status);
          return;
        }

        // Read the response as a stream
        const reader = response.body?.getReader();
        if (!reader) {
          console.error("No reader found on response body.");
          return;
        }

        const decoder = new TextDecoder("utf-8");
        let buffer = "";

        while (true) {
          const { done, value } = await reader.read();
          if (done) {
            break;
          }

          // Decode the current chunk
          const chunk = decoder.decode(value, { stream: true });
          buffer += chunk;

          // SSE typically separates messages by "\n\n"
          const parts = buffer.split("\n\n");

          // Keep the last partial chunk in the buffer
          buffer = parts.pop() || "";

          // Process each complete part
          for (let part of parts) {
            // Usually, SSE lines start with "data: "
            // e.g. "data: {...}\n" or "data: Stream closed\n"
            if (part.startsWith("data: ")) {
              const dataStr = part.replace(/^data:\s*/, "");
              console.log("[Stream Event] Raw data:", dataStr);

              // Save the raw data to display in JSX
              setRawMessages((prev) => prev + "\n" + dataStr);

              // Check for the "Stream closed" signal
              if (dataStr === "Stream closed") {
                console.log("[Stream Event] Received 'Stream closed'.");
                onStreamClosed(thinkingSteps);

                // We can stop reading further:
                controller.abort();
                return;
              }

              // Attempt to parse JSON
              try {
                const parsed = JSON.parse(dataStr);
                // If it’s an array of new thinking steps, append them
                // If it’s an object or another structure, handle accordingly
                if (Array.isArray(parsed)) {
                  setThinkingSteps((prev) => [...prev, ...parsed]);
                } else {
                  // If your server sometimes sends a single object,
                  // decide how you want to handle it
                  setThinkingSteps((prev) => [...prev, parsed]);
                }
              } catch (err) {
                console.warn("Failed to parse JSON from stream:", err);
              }
            }
          }
        }
      } catch (err) {
        if (!isCancelled) {
          console.error("[Stream Error]", err);
        }
      }
    }

    fetchThinkingStream();

    // Cleanup on unmount: stop the request
    return () => {
      isCancelled = true;
      controller.abort();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [apiEndpoint, token, reportId]);

  return (
    <div>
      <h1>Oracle Thinking</h1>
      <div>
        <strong>Accumulated Thinking Steps (parsed):</strong>
        <pre>{JSON.stringify(thinkingSteps, null, 2)}</pre>
      </div>
      <div>
        <strong>Raw Stream Messages:</strong>
        <pre>{rawMessages}</pre>
      </div>
    </div>
  );
}

