                    var settled_at = null;
                    var status = #pending;
                    var owner = {
                      owner = caller;
                      subaccount = null;
                    };
                  };
                  let escrow_result = await validate_and_prepare_intent_escrows(canister, nid, satisfying_intent, status.owner);
                  switch(escrow_result.error) {
                    case null {
                      let result = store_intent(status);
                      new_intent_id := ?result;
                      involved_intents.add(status);
                    };
                    case (?err) {
                      out.add(?#execute_intent(#Err({ error_code = 403; message = err })));
                      //continue eachRequest;
                    };
                  };
                };
                // Collect all involved intents (existing + new if present)
                label procAll for (intent_id in intent_ids.vals()) {
                  let mintentOpt = Map.get(intent_registry, Map.nhash, intent_id);
                  switch(mintentOpt){
                    case null {};
                    case (?target) {
                      if(target.status == #open) {
                        involved_intents.add(target);
                      } else {
                        out.add(?#execute_intent(#Err({ error_code = 203; message = "Intent not open." })));
                        break procAll;
                      }
                    }
                  }
                };
                // If we have less than 2 intents, cannot match
                if (involved_intents.size() < 2) {
                  out.add(?#execute_intent(#Err({ error_code = 404; message = "Not enough open intents to match." })));
                } else {
                  // Multi-party matching logic
                  var all_satisfied = true;
                  // For each intent, check if its requirements are satisfied by the others
                  label checkall for (i in Iter.range(0,(involved_intents.size()-1))) {
                    let intent = involved_intents.get(i);
                    let req_toks = IntentsHelpers.extract_intent_tokens(intent.original_config);
                    let allow_partial = IntentsHelpers.has_allow_partial(intent.original_config);
                    let sat_toks = Buffer.Buffer<[TokenSpec]>(0);
                    // Gather all tokens offered by other parties
                    for (j in Iter.range(0,(involved_intents.size()-1))) {
                      if (j != i) {
                        let other = involved_intents.get(j);
                        let other_toks = IntentsHelpers.extract_intent_tokens(other.original_config);
                        sat_toks.add(other_toks);
                      }
                    };
                    // Flatten all tokens from others
                    let all_other_toks = Array.flatten(Buffer.toArray(sat_toks));
                    // If allow_partial, only one satisfying set allowed, check proportional
                    if (allow_partial) {
                      // For now, require full satisfaction (TODO: implement proportional logic)
                      if (not TokenHelpers.all_assets_satisfied(req_toks, all_other_toks)) {
                        all_satisfied := false;
                        break checkall;
                      }
                    } else {
                      // If intent has satisfying_tokens, must get at least one set
                      let satisfying_sets = IntentsHelpers.extract_satisfy_tokens(intent.original_config);
                      if (satisfying_sets.size() > 0) {
                        var found = false;
                        label satset for (satset in satisfying_sets.vals()) {
                          if (TokenHelpers.all_assets_satisfied(satset, all_other_toks)) {
                            found := true;
                            break satset;
                          }
                        };
                        if (not found) {
                          all_satisfied := false;
                          break checkall;
                        };
                      } else {
                        // Otherwise, must get all requested tokens
                        if (not TokenHelpers.all_assets_satisfied(req_toks, all_other_toks)) {
                          all_satisfied := false;
                          break checkall;
                        };
                      }
                    }
                  };
                  if (all_satisfied) {
                    // Mark all intents as fulfilled, record settlement
                    for (i in Iter.range(0,(involved_intents.size()-1))) {
                      let intent = involved_intents.get(i);
                      intent.status := #fulfilled(?natNow());
                      intent.settled_at := ?(caller, intent.intent_id);
                    };
                    out.add(?#execute_intent(#Ok({ id = intent_ids[0]; actions = [] })));
                    exec_ok := true;
                  } else {
                    out.add(?#execute_intent(#Err({ error_code = 400; message = "Not all intents are satisfied by the group." })));
                  }
                };
                if(not exec_ok) out.add(?#execute_intent(#Err({ error_code = 404; message = "No matching open intent found." })));
              };
              // End/cancel an intent (moves to error state.)
              case (#end_intent(iid)) {
                let intent = Map.get(intent_registry, Map.nhash, iid);
                switch(intent) {
