                    //record format is { id = iid; actions = [] }
                    out.add(?#end_intent(#Ok({ id = iid; actions = [] })));
                  }
                }
              };
              // Withdraw settlement for an escrow (requires owner match)
              case (#withdraw_settlement(es)) {
                //todo: make sure we don't refund fulfilled intents
                var found = false;
                label proc3 for ((eid, esc) in Map.entries(escrow_book)) {
                  if(esc.owner == es.owner and esc.target_intent_id == es.target_intent_id) {
                    ignore Map.remove(escrow_book, Map.nhash, eid); found := true; break proc3;
                  }
                };
                //record format is { id = iid; actions = [] }
                if(found) out.add(?#withdraw_settlement(#Ok({ id = 0; actions = [] })))
                //record format is { id = iid; actions = [] }
                else out.add(?#withdraw_settlement(#Err({ error_code = 404; message = "Escrow not found" })));
              };
              // Withdraw escrow for an escrow record belonging to account
              case (#withdraw_escrow(es)) {
                var found = false;
                label proc4 for ((eid, esc) in Map.entries(escrow_book)) {
                  if(esc.owner == es.owner and esc.target_intent_id == es.target_intent_id) {
