    // Helper: Validate and create intent escrows, returns (error, actions)
    private func validate_and_prepare_intent_escrows(
      canister: Principal,
      intent_id: Nat,
      features_vec: [ ?IntentFeature ],
      owner: Account
    ) : async ({ error: ?Text; actions: [TokenSpecResult] }) {
      let req_escrows = IntentsHelpers.extract_intent_escrows(features_vec);
      var actions = Buffer.Buffer<TokenSpecResult>(0);
      var error: ?Text = null;
      for (escrow in req_escrows.vals()) {
        let assets = IntentsHelpers.extract_assets_from_escrow(escrow);
        for (tok in assets.vals()) {
          let deposit_escrow_account = TokenHelpers.escrow_account_for_deposit(canister, tok, escrow.owner, escrow.counterparty, escrow.target_intent_id);
          let intent_escrow_account = TokenHelpers.escrow_account_for_intent(canister, intent_id, tok, escrow.owner, escrow.counterparty, escrow.target_intent_id);
          if (await TokenHelpers.asset_in_escrow(tok, deposit_escrow_account)) {
            // Move asset from deposit escrow to intent escrow
            let move_result = await TokenHelpers.move_asset_to_escrow(tok, deposit_escrow_account, intent_escrow_account);
            Debug.print("Moved asset from deposit escrow to intent escrow: " # debug_show(move_result));
            switch(move_result) {
              case (#Ok(transfer_ids)) {
                actions.add({
                  canister = tok.canister;
                  token_pointer = tok.token_pointer;
                  inventory = tok.inventory;
                  meta = tok.meta;
                  result = #Ok(transfer_ids);
                  sending_account = deposit_escrow_account;
                  receiving_account = intent_escrow_account;
                  namespace = null;
                  intent_id = ?intent_id;
                });
              };
              case (#Err(msg)) {
                Debug.print("Error moving asset from deposit escrow: " # debug_show(msg));
                error := ?msg;
                return { error = ?("Error moving asset from deposit escrow " # debug_show(msg)); actions = Buffer.toArray(actions) }
                //break proc5;
              }
            }
          } else if (await TokenHelpers.asset_in_escrow(tok, intent_escrow_account)) {
            // Already in correct escrow
            actions.add({
              canister = tok.canister;
              token_pointer = tok.token_pointer;
              inventory = tok.inventory;
              meta = tok.meta;
              result = #Ok([]);
              sending_account = owner;
              receiving_account = intent_escrow_account;
              namespace = null;
              intent_id = ?intent_id;
            });
          } else if (await TokenHelpers.has_approval(tok, owner, {owner = canister; subaccount = null})) {
            let move_result = await TokenHelpers.move_asset_to_escrow(tok, owner, intent_escrow_account);
            Debug.print("Move result: " # debug_show(move_result));
            switch(move_result) {
              case (#Ok(transfer_ids)) {
                Debug.print("Moved asset to escrow: " # debug_show(transfer_ids));
                actions.add({
                  canister = tok.canister;
                  token_pointer = tok.token_pointer;
                  inventory = tok.inventory;
                  meta = tok.meta;
                  result = #Ok(transfer_ids);
                  sending_account = owner;
                  receiving_account = intent_escrow_account;
                  namespace = null;
                  intent_id = ?intent_id;
                });
              };
