            error := ?"Asset not in escrow and no approval";
            return { error = ?"Asset not in escrow and no approval"; actions = Buffer.toArray(actions) }
            //break proc5;
          }
        }
      };
      { error; actions = Buffer.toArray(actions) }
    }

