export interface PeerConfiguration extends RTCConfiguration {
  /**
   * @internal
   */
  testproxyURL?: string
}

export interface LobbySettings {
  codeFormat?: 'default' | 'short'
  codeLength?: number
  maxPlayers?: number // Defaults to 4, use 0 for unlimited.
  password?: string
  public?: boolean
  customData?: { [key: string]: any }
  canUpdateBy?: 'creator' | 'leader' | 'anyone' | 'none'
}

export interface LobbyListEntry {
  code: string
  public: boolean
  playerCount: number
  maxPlayers: number
  hasPassword: boolean
  customData?: { [key: string]: any }
  leader?: string
  term: number
  createdAt: string
  updatedAt: string
}

interface Base {
  type: string
  rid?: string
}

export type SignalingPacketTypes =
| CandidatePacket
| ClosePacket
| ConnectedPacket
| ConnectPacket
| CreatePacket
| CredentialsPacket
| DescriptionPacket
| DisconnectedPacket
| DisconnectPacket
