import * as t from "io-ts";
import { isLeft } from "fp-ts/Either";
import { EmployeeListItem } from "./EmployeeListItem";
import { Employee, EmployeeT } from "../models/Employee";

export type EmployeesContainerProps = {
  filterText: string;
};

const EmployeesT = t.array(EmployeeT);

const employeesFetcher = async (url: string): Promise<Employee[]> => {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Failed to fetch employees at ${url}`);
  }
  const body = await response.json();
  const decoded = EmployeesT.decode(body);
  if (isLeft(decoded)) {
    throw new Error(`Failed to decode employees ${JSON.stringify(body)}`);
  }
  return decoded.right;
};

export function EmployeeListContainer({ filterText }: EmployeesContainerProps) {
  const encodedFilterText = encodeURIComponent(filterText);
  const { data, error, isLoading } = useSWR<Employee[], Error>(
    `/api/employees?filterText=${encodedFilterText}`,
    employeesFetcher
  );
  useEffect(() => {
    if (error != null) {
      console.error(`Failed to fetch employees filtered by filterText`, error);
    }
  }, [error, filterText]);
  if (data != null) {
    return data.map((employee) => (
      <EmployeeListItem employee={employee} key={employee.id} />
    ));
  }
  if (isLoading) {
    return <p>Loading employees...</p>;
  }
}

from openai import OpenAI
import re
from typing import List, Tuple
from math import gcd

# OpenAI 클라이언트 초기화
client = OpenAI(
    api_key="YOUR_API_KEY"
)  # 실제 키로 교체하세요

# --- IR 노드 정의 ---
class IRNode:
    def length(self) -> int: ...

class Lit(IRNode):
    def __init__(self, s: str):
        self.s = s
    def length(self) -> int:
        return len(self.s)

class Loop(IRNode):
    def __init__(self, child: IRNode, count: int):
        self.child = child
        self.count = count
    def length(self) -> int:
        return self.child.length() * self.count

class Concat(IRNode):
    def __init__(self, parts: List[IRNode]):
        self.parts = parts
    def length(self) -> int:
        return sum(p.length() for p in self.parts)

# --- IR 파싱 (한 글자 Lit) ---
def parse_ir(expr: str) -> IRNode:
    tokens = list(expr)
    i = 0
    def parse_concat() -> IRNode:
        nonlocal i
        parts: List[IRNode] = []
        while i < len(tokens) and tokens[i] != ')':
            c = tokens[i]
            if c.isalpha():
                parts.append(Lit(c)); i += 1
            elif c == '(':
                i += 1
                sub = parse_concat()
                if i < len(tokens) and tokens[i] == ')':
                    i += 1
                cnt = 1
                if i < len(tokens) and tokens[i] == '^':
                    i += 1
                    num_start = i
                    while i < len(tokens) and tokens[i].isdigit():
                        i += 1
                    cnt = int(expr[num_start:i])
                parts.append(Loop(sub, cnt) if cnt > 1 else sub)
            else:
                i += 1
        if not parts:
            return Lit("")
        return parts[0] if len(parts) == 1 else Concat(parts)
    return parse_concat()

# --- IR → 문자열 ---
def tree_to_str(node: IRNode) -> str:
    if isinstance(node, Lit):
        return node.s
    if isinstance(node, Loop):
        inner = tree_to_str(node.child)
        return inner if node.count == 1 else f"({inner})^{node.count}"
    return "".join(tree_to_str(ch) for ch in node.parts)

# --- 완전 전개 (작게만) ---
def expand_small(node: IRNode, limit: int = 10000) -> str:
    if isinstance(node, Lit):
        return node.s
    if isinstance(node, Loop):
        body = expand_small(node.child, limit)
        total = len(body) * node.count
        if total > limit:
            raise MemoryError
        return body * node.count
    out = []
    for ch in node.parts:
        out.append(expand_small(ch, limit))
    s = "".join(out)
    if len(s) > limit:
        raise MemoryError
    return s

# --- KMP 최소 주기 ---
def minimal_period(s: str) -> int:
    n = len(s)
    pi = [0]*n
    j = 0
    for i in range(1, n):
        while j>0 and s[i]!=s[j]:
            j = pi[j-1]
        if s[i]==s[j]:
            j+=1
            pi[i]=j
    p = n - pi[-1]
    return p if n%p==0 else n

# --- 회전 최소주기 패턴 ---
def cyclic_minimal_base(s: str) -> str:
    n = len(s)
    best = s
    best_p = n
    for i in range(n):
        rot = s[i:]+s[:i]
        p = minimal_period(rot)
        if p < best_p:
            best_p, best = p, rot[:p]
    return best

# --- 루프 바운더리 정규화 ---
def normalize_loop_node(loop: Loop) -> IRNode:
    try:
        body = expand_small(loop.child)
    except MemoryError:
        return loop
    base = cyclic_minimal_base(body)
    if base != body:
        new_child = parse_ir(base)
        times = loop.count * (len(body)//len(base))
        return normalize_loop_node(Loop(new_child, times))
    return loop

# --- 마지막 Concat 내부에도 작은 반복 합치기 ---
def collapse_concat_loops(node: IRNode, seg_limit: int=1000) -> IRNode:
    if isinstance(node, Concat):
        parts = node.parts
        out = []
        i = 0
        while i < len(parts):
            # 가능한 연속 리터럴/단순 루프 블록 찾기
            j = i
            while j < len(parts) and (
                isinstance(parts[j], Lit)
                or (isinstance(parts[j], Loop) and isinstance(parts[j].child, Lit))
            ):
                j += 1
            if j - i >= 2:
                segment = Concat(parts[i:j])
                try:
                    s = expand_small(segment, limit=seg_limit)
                    p = minimal_period(s)
                    if p < len(s):
                        times = len(s)//p
                        out.append(Loop(Lit(s[:p]), times))
                        i = j
                        continue
                except MemoryError:
                    pass
            out.append(parts[i])
            i += 1
        return out[0] if len(out)==1 else Concat(out)
    return node

# --- canonicalize: 중첩+인접 합치기 + 바운더리 최소화 + collapse_concat_loops ---
def canonicalize_ir(node: IRNode) -> IRNode:
    if isinstance(node, Lit):
        return node
    if isinstance(node, Loop):
        child = canonicalize_ir(node.child)
        merged = Loop(child, node.count)
        if isinstance(child, Loop):
            merged = Loop(child.child, child.count*node.count)
        merged = normalize_loop_node(merged)
        return merged
    # Concat
    parts = [canonicalize_ir(p) for p in node.parts]
    merged: List[IRNode] = []
    for p in parts:
        if merged and isinstance(merged[-1], Lit) and isinstance(p, Lit):
            merged[-1] = Lit(merged[-1].s + p.s)
        elif merged and isinstance(merged[-1], Loop) and isinstance(p, Loop):
            if tree_to_str(merged[-1].child) == tree_to_str(p.child):
                merged[-1] = Loop(merged[-1].child, merged[-1].count + p.count)
            else:
                merged.append(p)
        else:
            merged.append(p)
    node2 = merged[0] if len(merged)==1 else Concat(merged)
    # 이 단계에서 작은 반복까지 반드시 합친다
    return collapse_concat_loops(node2)

# --- flatten ---
def flatten_ir(node: IRNode) -> List[Tuple[str,int]]:
    if isinstance(node, Lit):
        return [(node.s,1)]
    if isinstance(node, Loop):
        flat = flatten_ir(node.child)
        return [(s, c*node.count) for s,c in flat]
    out: List[Tuple[str,int]] = []
    for ch in node.parts:
        out += flatten_ir(ch)
    return out

# --- 회전 토큰 정규화 ---
def normalize_rotation(s:str)->str:
    if len(s)<=1: return s
    rots=[s[i:]+s[:i] for i in range(len(s))]
    return min(rots)

# --- align_loops & rebuild_ir (이전과 동일) ---
def align_loops(t1:IRNode,t2:IRNode)->Tuple[List[Tuple[str,int]],List[Tuple[str,int]]]:
    def lcm(a,b): return a//gcd(a,b)*b
    f1,f2=flatten_ir(t1),flatten_ir(t2)
    n=min(len(f1),len(f2))
    a1,a2=[],[]
    for i in range(n):
        s1,c1=f1[i]; s2,c2=f2[i]
        k1,k2=normalize_rotation(s1), normalize_rotation(s2)
        if k1==k2:
            m=lcm(c1,c2)
            a1.append((k1,m)); a2.append((k2,m))
        else:
            a1.append((s1,c1)); a2.append((s2,c2))
    a1+=f1[n:]; a2+=f2[n:]
    return a1,a2

def rebuild_ir(rle:List[Tuple[str,int]])->IRNode:
    parts:List[IRNode]=[]
    for s,k in rle:
        node:IRNode=Lit(s)
        if k>1: node=Loop(node,k)
        parts.append(node)
    return parts[0] if len(parts)==1 else Concat(parts)

# --- GPT 호출 & main ---
def ask_gpt(prompt:str)->str:
    resp = client.chat.completions.create(
        model="gpt-4.1",
        messages=[
            {"role":"system","content":"You are an expert in string pattern analysis."},
            {"role":"user","content":prompt}
        ],
        temperature=0
    )
    txt = resp.choices[0].message.content.strip().upper()
    return 'O' if 'O' in txt else 'X' if 'X' in txt else '?'

def run_checker(rule_path:str, data_path:str):
    rule = open(rule_path,encoding='utf-8').read().strip()
    total=correct=0
    with open(data_path,encoding='utf-8') as f:
        for line in f:
            parts=line.split()
            if len(parts)!=3: continue
            s1,s2,gt=parts
            try:
                t1=canonicalize_ir(parse_ir(s1))
                t2=canonicalize_ir(parse_ir(s2))
                r1,r2=align_loops(t1,t2)
                c1=canonicalize_ir(rebuild_ir(r1))
                c2=canonicalize_ir(rebuild_ir(r2))
                norm1,norm2=tree_to_str(c1),tree_to_str(c2)
            except:
                norm1,norm2=s1,s2

            prompt = (
                f"{rule}\n\n"
                "Q: Are the following two folded strings functionally equivalent?\n"
                f"String A: {norm1}\n"
                f"String B: {norm2}\n"
                "Answer with only one letter: O or X.\n"
                "A:"
            )
            pred=ask_gpt(prompt)
            total+=1
            if pred==gt: correct+=1
            mark="✔️" if pred==gt else "❌"
            print(f"[{total}] GT:{gt} Pred:{pred} | NormA:{norm1} | NormB:{norm2} {mark}")

    print(f"\n✅ Accuracy: {correct}/{total} = {correct/total:.2%}")

if __name__=="__main__":
    run_checker(
        "Yeom/Code/Test/Problem1/rule/fewshot.txt",
        "Yeom/Data/Data1.txt"
    )

